import sqlite3


class StudentDatabaseProcessor:

    CREATE_TABLE_SQL = """
        CREATE TABLE IF NOT EXISTS students (
            id INTEGER PRIMARY KEY,
            name TEXT,
            age INTEGER,
            gender TEXT,
            grade INTEGER
        )
    """

    INSERT_STUDENT_SQL = """
        INSERT INTO students (name, age, gender, grade)
        VALUES (?, ?, ?, ?)
    """

    SELECT_STUDENT_BY_NAME_SQL = "SELECT * FROM students WHERE name = ?"

    DELETE_STUDENT_BY_NAME_SQL = "DELETE FROM students WHERE name = ?"

    def __init__(self, database_name):
        self.database_name = database_name

    def _get_connection(self):
        return sqlite3.connect(self.database_name)

    def _execute_query(self, query, params=None, commit=False):
        conn = None
        cursor = None
        try:
            conn = self._get_connection()
            cursor = conn.cursor()
            cursor.execute(query, params or ())
            if commit:
                conn.commit()
        finally:
            if conn:
                conn.close()

    def _fetch_all(self, query, params=None):
        conn = self._get_connection()
        try:
            cursor = conn.cursor()
            cursor.execute(query, params or ())
            return cursor.fetchall()
        finally:
            conn.close()

    def create_student_table(self):
        self._execute_query(self.CREATE_TABLE_SQL, commit=True)

    def insert_student(self, student_data):
        params = (
            student_data['name'],
            student_data['age'],
            student_data['gender'],
            student_data['grade']
        )
        self._execute_query(self.INSERT_STUDENT_SQL, params=params, commit=True)

    def search_student_by_name(self, name):
        return self._fetch_all(self.SELECT_STUDENT_BY_NAME_SQL, params=(name,))

    def delete_student_by_name(self, name):
        self._execute_query(self.DELETE_STUDENT_BY_NAME_SQL, params=(name,), commit=True)
